export const UnexpectedColumns: string[] = [
	ColumnId.UnexpectedTotal,
	ColumnId.PassedUnexpected,
	ColumnId.FailedUnexpected,
	ColumnId.SkippedUnexpected,
	ColumnId.Abnormal
];

const createUnexpectedColumnGetter =
	(unexpectedColumns: string[]) => (columnId: string) =>
		unexpectedColumns.includes(columnId);

export const getUnexpectedResultForColumnId = (
	columnId: string
): ResultTableFilter => {
	switch (columnId) {
		case ColumnId.UnexpectedTotal:
			return {
				results: [
					RESULT_TYPE.Passed,
					RESULT_TYPE.Failed,
					RESULT_TYPE.Killed,
					RESULT_TYPE.Cored,
					RESULT_TYPE.Skipped,
					RESULT_TYPE.Incomplete,
					RESULT_TYPE.Faked
				],
				resultProperties: [RESULT_PROPERTIES.Unexpected]
			};
		case ColumnId.PassedUnexpected:
			return {
				results: [RESULT_TYPE.Passed],
				resultProperties: [RESULT_PROPERTIES.Unexpected]
			};
		case ColumnId.FailedUnexpected:
			return {
				results: [RESULT_TYPE.Failed, RESULT_TYPE.Killed, RESULT_TYPE.Cored],
				resultProperties: [RESULT_PROPERTIES.Unexpected]
			};
		case ColumnId.SkippedUnexpected:
			return {
				results: [RESULT_TYPE.Skipped],
				resultProperties: [RESULT_PROPERTIES.Unexpected]
			};
		default:
			return {
				results: [],
				resultProperties: []
			};
	}
};

export const isUnexpectedColumn =
	createUnexpectedColumnGetter(UnexpectedColumns);

export const DEFAULT_COLUMN_VISIBILITY: VisibilityState = {
	[ColumnId.Total]: false,
	[ColumnId.ExpectedTotal]: false,
	[ColumnId.UnexpectedTotal]: false,
	[ColumnId.Objective]: true,
	[ColumnId.Comments]: false
};

const RUN_STATS_COLUMN_ID_MAP: Record<RunStatsColumn, ColumnId> = {
	run: ColumnId.Run,
	passed: ColumnId.PassedExpected,
	failed: ColumnId.FailedExpected,
	passed_unexpected: ColumnId.PassedUnexpected,
	failed_unexpected: ColumnId.FailedUnexpected,
	skipped: ColumnId.SkippedExpected,
	skipped_unexpected: ColumnId.SkippedUnexpected,
	abnormal: ColumnId.Abnormal,
	comments: ColumnId.Comments,
	objective: ColumnId.Objective,
	total: ColumnId.Total,
	total_expected: ColumnId.ExpectedTotal,
	total_unexpected: ColumnId.UnexpectedTotal
};

const CONFIGURABLE_COLUMN_IDS = [
	ColumnId.Total,
	ColumnId.Run,
	ColumnId.ExpectedTotal,
	ColumnId.UnexpectedTotal,
	ColumnId.PassedExpected,
	ColumnId.FailedExpected,
	ColumnId.PassedUnexpected,
	ColumnId.FailedUnexpected,
	ColumnId.SkippedExpected,
	ColumnId.SkippedUnexpected,
	ColumnId.Abnormal,
	ColumnId.Objective,
	ColumnId.Comments
];

export const DEFAULT_COLUMN_ORDER = [
	ColumnId.Tree,
	ColumnId.Objective,
	ColumnId.Comments,
	...CONFIGURABLE_COLUMN_IDS.filter(
		(columnId) =>
			columnId !== ColumnId.Objective && columnId !== ColumnId.Comments
	)
];

export function createDefaultColumnVisibility(
	defaultColumns?: RunStatsColumn[]
): VisibilityState {
	if (!defaultColumns) return DEFAULT_COLUMN_VISIBILITY;

	const visibleColumns = new Set(
		defaultColumns.map((column) => RUN_STATS_COLUMN_ID_MAP[column])
	);

	return CONFIGURABLE_COLUMN_IDS.reduce<VisibilityState>((acc, columnId) => {
		acc[columnId] = visibleColumns.has(columnId);

		return acc;
	}, {});
}

export function createDefaultColumnOrder(
	defaultColumns?: RunStatsColumn[]
): ColumnId[] {
	if (!defaultColumns) return DEFAULT_COLUMN_ORDER;

	const orderedColumnIds = Array.from(
		new Set(defaultColumns.map((column) => RUN_STATS_COLUMN_ID_MAP[column]))
	);
	const orderedColumnIdsSet = new Set(orderedColumnIds);
	const restColumnIds = CONFIGURABLE_COLUMN_IDS.filter(
		(columnId) => !orderedColumnIdsSet.has(columnId)
	);

	return [ColumnId.Tree, ...orderedColumnIds, ...restColumnIds];
}

/**
 * Reconciles a user-saved column order against the current default order.
 *
 * Keeps the saved order for columns that still exist, drops columns the API no
 * longer provides, appends newly added columns in their default position, and
 * always pins the tree column first. This protects against stale localStorage
 * when the available column set changes.
 */
export function reconcileColumnOrder(
	saved: ColumnId[] | undefined | null,
	defaultOrder: ColumnId[]
): ColumnId[] {
	if (!saved || saved.length === 0) return defaultOrder;

	const defaultSet = new Set(defaultOrder);
	const knownSaved = saved.filter(
		(columnId) => columnId !== ColumnId.Tree && defaultSet.has(columnId)
	);
	const knownSet = new Set(knownSaved);
	const missing = defaultOrder.filter(
		(columnId) => columnId !== ColumnId.Tree && !knownSet.has(columnId)
	);

	return [ColumnId.Tree, ...knownSaved, ...missing];
}

